<template>
    <div class="notification"
         :class="[typeClass, {'closing': isClosing, 'hovering': isHovering}]"
         @mouseenter="handleMouseEnter"
         @mouseleave="handleMouseLeave"
         @click="dismiss"
         @mousedown="handleMouseDown"
         @mouseup="handleMouseUp">
        <button class="dismiss-btn" @click.stop="dismiss">
            <i class="fas fa-times"></i>
        </button>
        <div class="icon-container">
            <i :class="iconClass"></i>
        </div>
        <div class="Ncontent">
            <div class="notification-message">{{ message }}</div>
        </div>
        <div class="progress-bar" v-if="showProgress">
            <div class="progress" :style="{ width: progressWidth }"></div>
        </div>
    </div>
</template>

<script>
    export default {
        props: {
            message: {
                type: String,
                default: ''
            },
            type: {
                type: String,
                default: 'info',
                validator: value => ['error', 'warning', 'info', 'success'].includes(value)
            },
            id: {
                type: String,
                required: true
            }
        },
        data() {
            return {
                isClosing: false,
                isHovering: false,
                isMouseDown: false,
                showProgress: true,
                progressWidth: '100%',
                timeoutId: null,
                animationId: null,
                startTime: 0,
                initialDuration: 0,
                remainingTime: 0,
                timeFactor: 1
            };
        },
        computed: {
            typeClass() {
                return `notification-${this.type}`;
            },
            iconClass() {
                const icons = {
                    error: 'fas fa-exclamation-circle',
                    warning: 'fas fa-exclamation-triangle',
                    info: 'fas fa-info-circle',
                    success: 'fas fa-check-circle'
                };
                return icons[this.type];
            }
        },
        mounted() {
            this.startAutoDismiss();
        },
        beforeUnmount() {
            this.cancelAnimations();
        },
        methods: {
            startAutoDismiss() {
                const charsPerSecond = 15;
                const baseDuration = 5000;
                this.initialDuration = Math.max(
                    5000,
                    baseDuration + (this.message.length / charsPerSecond) * 1000 * 1.2
                );
                this.remainingTime = this.initialDuration;
                this.startTime = Date.now();
                this.updateProgress();
            },

            updateProgress() {
                const now = Date.now();
                const elapsed = now - this.startTime;

                const effectiveElapsed = elapsed * this.timeFactor;
                this.remainingTime = Math.max(0, this.initialDuration - effectiveElapsed);

                this.progressWidth = `${(this.remainingTime / this.initialDuration) * 100}%`;

                if (this.remainingTime > 0) {
                    this.animationId = requestAnimationFrame(this.updateProgress);
                } else {
                    this.dismiss();
                }
            },

            handleMouseEnter() {
                this.isHovering = true;
                this.timeFactor = 0.3;
                this.startTime = Date.now();
            },

            handleMouseLeave() {
                this.isHovering = false;
                this.timeFactor = 1;
                this.startTime = Date.now();
            },

            handleMouseDown() {
                this.isMouseDown = true;
            },

            handleMouseUp() {
                this.isMouseDown = false;
            },

            dismiss() {
                if (this.isClosing) return;
                this.isClosing = true;
                this.showProgress = false;
                this.cancelAnimations();

                setTimeout(() => {
                    this.$emit('dismiss', this.id);
                }, 300);
            },

            cancelAnimations() {
                if (this.timeoutId) {
                    clearTimeout(this.timeoutId);
                    this.timeoutId = null;
                }
                if (this.animationId) {
                    cancelAnimationFrame(this.animationId);
                    this.animationId = null;
                }
            }
        }
    };
</script>

