<!-- src/components/MonitorStream.vue -->
<template>
    <div class="monitor-stream-container">
        <!-- 流显示区域 -->
        <div class="stream-content">
            <img 
                :src="streamUrl" 
                alt="摄像头流"
                class="stream-image"
                @error="handleStreamError"
                @load="handleStreamLoad"
                :style="{ display: streaming ? 'block' : 'none' }"
            />
            <div v-if="!streaming" class="stream-placeholder">
                <div class="placeholder-content">
                    <div class="icon">📷</div>
                    <p>点击"开始"按钮启动流</p>
                </div>
            </div>
        </div>

        <!-- 错误状态 -->
        <div v-if="error" class="error-overlay">
            <div class="error-content">
                <h4>流错误</h4>
                <p>{{ error }}</p>
                <button class="btn-small btn-primary" @click="reconnect">
                    重新连接
                </button>
            </div>
        </div>

        <!-- 加载状态 -->
        <div v-if="loading" class="loading-overlay">
            <div class="loading-spinner"></div>
            <p>加载中...</p>
        </div>

        <!-- 控制按钮 -->
        <div class="stream-controls">
            <button 
                class="control-btn"
                :class="{ 'btn-danger': streaming }"
                @click="toggleStream"
                :disabled="loading"
            >
                {{ streaming ? '停止' : '开始' }}
            </button>
            <button 
                class="control-btn"
                @click="reconnect"
                :disabled="loading || !streaming"
            >
                刷新
            </button>
        </div>
    </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { cameraApi, deviceApi } from '@/services/stpApi';
import { macNicknameService } from '@/services/macNicknameService';
import { websocketService } from '@/services/websocketService';

// Props
const props = defineProps({
    serverIp: {
        type: String,
        default: ''
    },
    serverPort: {
        type: [String, Number],
        default: ''
    },
    roomId: {
        type: String,
        default: ''
    },
    type: {
        type: String,
        default: 'tcp'
    },
    streaming: {
        type: Boolean,
        default: false
    },
    deviceMac: {
        type: String,
        default: ''
    },
    relayIp: {
        type: String,
        default: ''
    },
    relayPort: {
        type: [String, Number],
        default: ''
    }
});

// Emits
const emit = defineEmits(['status-change', 'room-id-change']);

// 响应式数据
const error = ref('');
const loading = ref(false);
const streamKey = ref(0); // 用于强制刷新流

// 计算属性
const streamUrl = computed(() => {
    if (!props.streaming) return '';
    // 添加时间戳防止缓存
    const timestamp = new Date().getTime();
    if (props.type === 'tcp') {
        return `${cameraApi.getStream(props.serverIp, props.serverPort)}&t=${timestamp}&key=${streamKey.value}`;
    } else if (props.type === 'relay') {
        return `${cameraApi.getRelayStream(props.roomId)}&t=${timestamp}&key=${streamKey.value}`;
    }
    return '';
});

// 监听streaming属性变化
watch(() => props.streaming, (newValue) => {
    if (newValue) {
        startStream();
    } else {
        stopStream();
    }
});

// 处理流错误
const handleStreamError = () => {
    if (streamUrl.value != '') {
    error.value = '无法连接到摄像头，请检查设备是否在线';
    emit('status-change', false);
    }
};

// 处理流加载成功
const handleStreamLoad = () => {
    error.value = '';
    loading.value = false;
    emit('status-change', true);
};

// 开始流
const startStream = async () => {
    if (!props.streaming) return;
    
    loading.value = true;
    error.value = '';
    
    try {
        // 重置流key以强制刷新
        streamKey.value++;
        
        // 中继模式下额外触发一次刷新
        if (props.type === 'relay' && props.deviceMac && props.relayIp && props.relayPort) {
            await reconnect();
        }
        
        // 等待一段时间让流加载
        setTimeout(() => {
            if (loading.value) {
                error.value = '流加载超时';
                loading.value = false;
                emit('status-change', false);
            }
        }, 10000);
    } catch (err) {
        error.value = '启动流失败: ' + err.message;
        loading.value = false;
        emit('status-change', false);
    }
};

// 停止流
const stopStream = () => {
    error.value = '';
    loading.value = false;
    emit('status-change', false);
};

// 切换流状态
const toggleStream = () => {
    emit('status-change', !props.streaming);
};

// 重新连接
const reconnect = async () => {
    if (!props.streaming) return;
    
    error.value = '';
    loading.value = true;
    streamKey.value++;
    
    if (props.type === 'relay' && props.deviceMac && props.relayIp && props.relayPort) {
        try {
            // 获取设备的昵称短语
            const target = macNicknameService.getDeviceNickname(props.deviceMac);
            // 启动中继流
            await deviceApi.startRelayStreaming(target, props.relayIp, props.relayPort);
            
            // 订阅消息，处理房间号更新
            const messageHandler = (data) => {
                if (data.message) {
                    try {
                        const messageData = JSON.parse(data.message);
                        // 检查消息是否来自目标设备
                        if (messageData.user === target) {
                            // 检查消息内容是否包含房间号
                            if (messageData.msg && messageData.msg.startsWith('camera.relay_room')) {
                                // 提取房间号
                                const parts = messageData.msg.split(' ');
                                if (parts.length >= 4) {
                                    const roomId = parts[3];
                                    // 发送房间号更新事件
                                    emit('room-id-change', roomId);
                                }
                            }
                        }
                    } catch (e) {
                        console.error('解析消息失败:', e);
                    }
                }
            };
            
            // 订阅消息
            websocketService.subscribeMessages(messageHandler);
            
            // 10秒后取消订阅
            setTimeout(() => {
                websocketService.unsubscribeMessages(messageHandler);
            }, 10000);
        } catch (e) {
            error.value = '启动中继流失败';
            loading.value = false;
            emit('status-change', false);
        }
    }
    
    setTimeout(() => {
        if (loading.value) {
            error.value = '重连超时';
            loading.value = false;
            emit('status-change', false);
        }
    }, 10000);
};
</script>

<style scoped>
.monitor-stream-container {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 250px;
}

.stream-content {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 250px;
    background-color: #000;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.stream-image {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

.stream-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #1a1a1a;
    color: #666;
}

.placeholder-content {
    text-align: center;
}

.placeholder-content .icon {
    font-size: 48px;
    margin-bottom: 16px;
    opacity: 0.5;
}

.placeholder-content p {
    margin: 0;
    font-size: 14px;
}

/* 错误和加载覆盖层 */
.error-overlay,
.loading-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.7);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: white;
    z-index: 10;
}

.error-content {
    text-align: center;
    padding: 20px;
    background-color: rgba(244, 67, 54, 0.8);
    border-radius: 8px;
    max-width: 80%;
}

.error-content h4 {
    margin: 0 0 10px 0;
}

.error-content p {
    margin: 0 0 20px 0;
    font-size: 14px;
}

.loading-spinner {
    border: 4px solid rgba(255, 255, 255, 0.3);
    border-radius: 50%;
    border-top: 4px solid white;
    width: 40px;
    height: 40px;
    animation: spin 1s linear infinite;
    margin-bottom: 16px;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* 控制按钮 */
.stream-controls {
    position: absolute;
    bottom: 10px;
    right: 10px;
    display: flex;
    gap: 10px;
    z-index: 5;
}

.control-btn {
    padding: 8px 16px;
    border: none;
    border-radius: 4px;
    background-color: rgba(35, 66, 255, 0.8);
    color: white;
    cursor: pointer;
    font-size: 12px;
    transition: all 0.3s;
}

.control-btn:hover {
    background-color: rgba(8, 0, 202, 0.9);
}

.control-btn:disabled {
    background-color: rgba(158, 158, 158, 0.6);
    cursor: not-allowed;
}

.control-btn.btn-danger {
    background-color: rgba(244, 67, 54, 0.8);
}

.control-btn.btn-danger:hover {
    background-color: rgba(211, 47, 47, 0.9);
}

/* 响应式设计 */
@media (max-width: 768px) {
    .stream-controls {
        position: static;
        margin-top: 10px;
        justify-content: center;
    }
    
    .control-btn {
        padding: 10px 20px;
        font-size: 14px;
    }
}
</style>