<!-- src/views/Monitor.vue -->
<template>
    <div class="control-container">
        <div class="header">
            <h1><i class="fas fa-camera"></i> 智能监控系统</h1>
            <nav class="main-nav">
                <ul>
                    <li>
                        <router-link to="/control" class="nav-link" active-class="active">
                            <i class="fas fa-desktop"></i> 设备控制
                        </router-link>
                    </li>
                    <li>
                        <router-link to="/monitor" class="nav-link" active-class="active">
                            <i class="fas fa-video"></i> 监控中心
                        </router-link>
                    </li>
                </ul>
            </nav>
        </div>

        <div class="content">
            <div class="header-actions">
                <button class="btn-primary" @click="showAddCameraDialog = true">
                    添加摄像头
                </button>
                <div class="layout-selector">
                    <label>布局：</label>
                    <select v-model="selectedLayout" @change="updateLayout">
                        <option value="1">单路</option>
                        <option value="2">双路</option>
                        <option value="3">三路</option>
                        <option value="4">四路</option>
                    </select>
                </div>
            </div>

            <!-- 摄像头网格 -->
            <div class="camera-grid" :class="`layout-${selectedLayout}`">
                <div 
                    v-for="(camera, index) in cameras" 
                    :key="camera.id"
                    class="camera-item"
                >
                    <div class="camera-header">
                        <h3>{{ camera.name }}</h3>
                        <div class="camera-actions">
                            <button class="btn-small" @click="startStream(camera)">
                                {{ camera.streaming ? '停止' : '开始' }}
                            </button>
                            <button class="btn-small btn-danger" @click="removeCamera(camera.id)">
                                删除
                            </button>
                        </div>
                    </div>
                    <div class="camera-stream">
                        <MonitorStream 
                            :server-ip="camera.ip"
                            :server-port="camera.port"
                            :room-id="camera.roomId"
                            :type="camera.type || 'tcp'"
                            :streaming="camera.streaming"
                            :device-mac="camera.deviceMac"
                            :relay-ip="camera.relayIp"
                            :relay-port="camera.relayPort"
                            @status-change="handleStreamStatusChange(camera.id, $event)"
                            @room-id-change="handleRoomIdChange(camera.id, $event)"
                        />
                    </div>
                    <div class="camera-info">
                        <span v-if="camera.type === 'tcp'">IP: {{ camera.ip }}</span>
                        <span v-if="camera.type === 'tcp'">端口: {{ camera.port }}</span>
                        <span v-if="camera.type === 'relay'">设备: {{ getDeviceShowName(camera.deviceMac) }}</span>
                        <span v-if="camera.type === 'relay'">房间号: {{ camera.roomId }}</span>
                        <span>状态: {{ camera.streaming ? '在线' : '离线' }}</span>
                        <span>类型: {{ camera.type === 'relay' ? '中继' : 'TCP' }}</span>
                    </div>
                </div>
            </div>

            <!-- 空状态 -->
            <div v-if="cameras.length === 0" class="empty-state">
                <h3>暂无摄像头</h3>
                <p>点击"添加摄像头"按钮添加监控设备</p>
            </div>
        </div>

        <!-- 添加摄像头对话框 -->
        <div v-if="showAddCameraDialog" class="dialog-overlay">
            <div class="dialog">
                <h3>添加摄像头</h3>
                <div class="form-group">
                    <label>摄像头名称</label>
                    <input type="text" v-model="newCamera.name" placeholder="请输入摄像头名称">
                </div>
                <div class="form-group">
                    <label>摄像头类型</label>
                    <select v-model="newCamera.type" @change="handleCameraTypeChange">
                        <option value="tcp">TCP流媒体</option>
                        <option value="relay">中继流媒体</option>
                    </select>
                </div>
                <div v-if="newCamera.type === 'tcp'" class="form-group">
                    <label>服务器IP</label>
                    <input type="text" v-model="newCamera.ip" placeholder="请输入服务器IP">
                </div>
                <div v-if="newCamera.type === 'tcp'" class="form-group">
                    <label>服务器端口</label>
                    <input type="number" v-model="newCamera.port" placeholder="请输入服务器端口">
                </div>
                <div v-if="newCamera.type === 'relay'" class="form-group">
                    <label>设备</label>
                    <div class="device-selector">
                        <select v-model="newCamera.deviceMac" class="device-select">
                            <option v-for="device in allDevices" :key="device.mac" :value="device.mac">
                                {{ getDeviceShowName(device.mac) }}
                            </option>
                            <option v-if="allDevices.length === 0" value="">
                                无可用设备
                            </option>
                        </select>
                        <button class="btn-refresh" @click="fetchDevices" :disabled="isFetchingDevices">
                            <i class="fas fa-sync-alt" :class="{ 'spinning': isFetchingDevices }"></i>
                        </button>
                    </div>
                </div>
                <div v-if="newCamera.type === 'relay'" class="form-group">
                    <label>中继服务器IP</label>
                    <input type="text" v-model="newCamera.relayIp" placeholder="请输入中继服务器IP">
                </div>
                <div v-if="newCamera.type === 'relay'" class="form-group">
                    <label>中继服务器端口</label>
                    <input type="number" v-model="newCamera.relayPort" placeholder="请输入中继服务器端口">
                </div>
                <div v-if="newCamera.type === 'relay'" class="form-group">
                    <label>房间号</label>
                    <div class="room-selector">
                        <select v-model="newCamera.roomId" class="room-select">
                            <option v-for="room in relayRooms" :key="room" :value="room">
                                {{ room }}
                            </option>
                            <option v-if="relayRooms.length === 0" value="">
                                无可用房间
                            </option>
                        </select>
                        <button class="btn-refresh" @click="fetchRelayRooms" :disabled="isFetchingRooms">
                            <i class="fas fa-sync-alt" :class="{ 'spinning': isFetchingRooms }"></i>
                        </button>
                    </div>
                </div>
                <div class="dialog-actions">
                    <button class="btn-secondary" @click="showAddCameraDialog = false">
                        取消
                    </button>
                    <button class="btn-primary" @click="addCamera" :disabled="newCamera.type === 'relay' && (!newCamera.deviceMac || !newCamera.relayIp || !newCamera.relayPort || !newCamera.roomId)">
                        添加
                    </button>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
import { ref, onMounted, watch, onUnmounted } from 'vue';
import MonitorStream from '@/components/MonitorStream.vue';
import { useMonitor } from '@/composables/useMonitor';
import { useDeviceControl } from '@/composables/useDeviceControl';
import { relayApi } from '@/services/stpApi';
import { showGlobalNotification } from '@/utils/notificationHandler.js';

const { 
    cameras, 
    addCamera: addCameraToStore, 
    removeCamera: removeCameraFromStore,
    startStream: startStreamFromStore,
    stopStream: stopStreamFromStore
} = useMonitor();

const {
    allDevices,
    getDeviceShowName,
    sendDiscoveryMessage,
    startDeviceDiscovery,
    stopDeviceDiscovery
} = useDeviceControl();

// 响应式数据
const selectedLayout = ref('1');
const showAddCameraDialog = ref(false);
const newCamera = ref({
    name: '',
    type: 'tcp',
    ip: '',
    port: '',
    roomId: '',
    deviceMac: '',
    relayIp: '',
    relayPort: ''
});
const relayRooms = ref([]);
const isFetchingRooms = ref(false);
const isFetchingDevices = ref(false);

// 生命周期
onMounted(() => {
    // 加载保存的摄像头列表
    loadCameras();
    // 启动设备发现
    startDeviceDiscovery();
});

// 组件卸载时停止设备发现
onUnmounted(() => {
    stopDeviceDiscovery();
});

// 监听对话框显示，自动获取设备和房间列表
watch(showAddCameraDialog, (newVal) => {
    if (newVal) {
        // 延迟一点时间，确保对话框已经显示
        setTimeout(() => {
            if (newCamera.value.type === 'relay') {
                fetchDevices();
                fetchRelayRooms();
            }
        }, 100);
    }
});

// 加载摄像头列表
const loadCameras = () => {
    const savedCameras = localStorage.getItem('cameras');
    if (savedCameras) {
        try {
            const parsedCameras = JSON.parse(savedCameras);
            parsedCameras.forEach(camera => {
                addCameraToStore(camera);
            });
        } catch (error) {
            showGlobalNotification('加载摄像头列表失败', 'error');
        }
    }
};

// 保存摄像头列表
const saveCameras = () => {
    localStorage.setItem('cameras', JSON.stringify(cameras.value));
};

// 处理摄像头类型切换
const handleCameraTypeChange = () => {
    if (newCamera.value.type === 'relay') {
        fetchDevices();
        fetchRelayRooms();
    }
};

// 获取设备列表
const fetchDevices = async () => {
    isFetchingDevices.value = true;
    try {
        await sendDiscoveryMessage();
    } finally {
        // 设备发现需要一些时间，所以延迟一点再设置为false
        setTimeout(() => {
            isFetchingDevices.value = false;
        }, 2000);
    }
};

// 获取中继房间列表
const fetchRelayRooms = async () => {
    isFetchingRooms.value = true;
    try {
        const data = await relayApi.getRooms();
        relayRooms.value = data.rooms || [];
        // 自动选择第一个房间
        if (relayRooms.value.length > 0) {
            newCamera.value.roomId = relayRooms.value[0];
        }
    } catch (error) {
        // 错误处理已在relayApi中完成
    } finally {
        isFetchingRooms.value = false;
    }
};

// 添加摄像头
const addCamera = () => {
    if (newCamera.value.name) {
        let camera;
        
        if (newCamera.value.type === 'tcp') {
            if (!newCamera.value.ip || !newCamera.value.port) {
                showGlobalNotification('请填写完整的TCP摄像头信息', 'error');
                return;
            }
            
            camera = {
                id: Date.now().toString(),
                name: newCamera.value.name,
                type: 'tcp',
                ip: newCamera.value.ip,
                port: newCamera.value.port,
                streaming: false
            };
        } else if (newCamera.value.type === 'relay') {
            if (!newCamera.value.roomId) {
                showGlobalNotification('请选择房间号', 'error');
                return;
            }
            
            camera = {
                id: Date.now().toString(),
                name: newCamera.value.name,
                type: 'relay',
                roomId: newCamera.value.roomId,
                deviceMac: newCamera.value.deviceMac,
                relayIp: newCamera.value.relayIp,
                relayPort: newCamera.value.relayPort,
                streaming: false
            };
        }
        
        addCameraToStore(camera);
        saveCameras();
        
        // 重置表单
        newCamera.value = {
            name: '',
            type: 'tcp',
            ip: '',
            port: '',
            roomId: '',
            deviceMac: '',
            relayIp: '',
            relayPort: ''
        };
        
        showAddCameraDialog.value = false;
    }
};

// 删除摄像头
const removeCamera = (cameraId) => {
    removeCameraFromStore(cameraId);
    saveCameras();
};

// 开始/停止流
const startStream = (camera) => {
    if (camera.streaming) {
        stopStreamFromStore(camera.id);
    } else {
        startStreamFromStore(camera.id);
    }
    saveCameras();
};

// 处理流状态变化
const handleStreamStatusChange = (cameraId, status) => {
    const camera = cameras.value.find(c => c.id === cameraId);
    if (camera) {
        camera.streaming = status;
        saveCameras();
    }
};

// 处理房间号更新
const handleRoomIdChange = (cameraId, roomId) => {
    const camera = cameras.value.find(c => c.id === cameraId);
    if (camera) {
        camera.roomId = roomId;
        saveCameras();
    }
};

// 更新布局
const updateLayout = () => {
    // 布局更新逻辑
};
</script>

