<!-- views/Login.vue -->
<template>
    <div class="login-container">
        <div class="form-wrapper">
            <!-- 后端设置表单 -->
            <div class="settings-form" :class="{ 'show': showSettings }">
                <div class="settings-header">
                    <h3>后端设置</h3>
                    <Tooltip content="关闭设置">
                        <button class="close-btn" @click="showSettings = false">
                            <i class="fas fa-times"></i>
                        </button>
                    </Tooltip>
                </div>
                <div class="form-group">
                    <label for="backendIp">后端IP</label>
                    <input type="text"
                           id="backendIp"
                           v-model="backendConfig.ip"
                           placeholder="请输入后端IP">
                </div>
                <div class="form-group">
                    <label for="backendPort">后端端口</label>
                    <input type="number"
                           id="backendPort"
                           v-model="backendConfig.port"
                           placeholder="请输入后端端口">
                </div>
                <div class="settings-actions">
                    <button type="button"
                            class="btn-small btn-primary"
                            @click="saveSettings">
                        保存
                    </button>
                    <button type="button"
                            class="btn-small btn-secondary"
                            @click="resetSettings">
                        重置默认
                    </button>
                </div>
            </div>

            <!-- 登录表单 -->
            <div class="login-form" :class="{ 'with-settings': showSettings }">
                <div class="form-header">
                    <h2>用户登录</h2>
                    <Tooltip :content="showSettings ? '关闭后端设置' : '设置后端IP和端口'">
                        <button class="settings-btn" @click="showSettings = !showSettings">
                            <i :class="showSettings ? 'fas fa-times' : 'fas fa-cog'"></i>
                        </button>
                    </Tooltip>
                </div>

                <div class="form-group">
                    <label for="email">邮箱</label>
                    <input type="email"
                           id="email"
                           v-model="email"
                           placeholder="请输入邮箱"
                           @keyup.enter="handleLogin">
                </div>

                <div class="form-group">
                    <label for="password">密码</label>
                    <input type="password"
                           id="password"
                           v-model="password"
                           placeholder="请输入密码"
                           @keyup.enter="handleLogin">
                </div>

                <div class="form-actions">
                    <button type="button"
                            class="login-btn"
                            @click="handleLogin"
                            :disabled="loading">
                        {{ loading ? '登录中...' : '登录' }}
                    </button>

                    <div class="remember-me">
                        <input type="checkbox" id="remember" v-model="rememberMe">
                        <label for="remember">记住我</label>
                    </div>
                </div>

                <div v-if="error" class="error-message">
                    {{ error }}
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
    import { onMounted, ref } from 'vue';
    import { useRouter } from 'vue-router';
    import { useAuth } from '@/composables/useAuth';
    import { configService } from '@/services/configService';
    import { showGlobalNotification } from '@/utils/notificationHandler.js';
    import Tooltip from '@/components/Tooltip.vue';

    const router = useRouter();
    const {
        email,
        password,
        rememberMe,
        loading,
        error,
        login,
        checkAuth
    } = useAuth();

    // 后端设置相关
    const showSettings = ref(false);
    const backendConfig = ref({ 
        ip: 'localhost', 
        port: 5002 
    });

    onMounted(() => {
        checkAuth();
        loadSettings();
    });

    // 加载当前配置
    const loadSettings = () => {
        const config = configService.getConfig();
        backendConfig.value = {
            ip: config.backendIp,
            port: config.backendPort
        };
    };

    // 保存设置
    const saveSettings = () => {
        configService.saveConfig({
            backendIp: backendConfig.value.ip,
            backendPort: backendConfig.value.port
        });
        alert('设置已保存，请刷新页面以应用新配置');
    };

    // 重置默认设置
    const resetSettings = () => {
        const defaultConfig = configService.resetToDefault();
        backendConfig.value = {
            ip: defaultConfig.backendIp,
            port: defaultConfig.backendPort
        };
        alert('已重置为默认设置');
    };

    const handleLogin = async () => {
        const success = await login();

        if (success) {
            showGlobalNotification('登录成功！', 'success');
            router.push('/control');
        }
        // 如果失败，错误信息已经在 useAuth 中设置，这里不需要额外处理
    };
</script>

