// src/composables/useAuth.js
import { ref, computed } from 'vue';
import { useRouter } from 'vue-router';

export function useAuth() {
    const router = useRouter();

    // 用户状态
    const email = ref('');
    const password = ref('');
    const rememberMe = ref(false);
    const loading = ref(false);
    const error = ref('');

    // 计算属性
    const userInitial = computed(() => {
        return email.value ? email.value.charAt(0).toUpperCase() : 'U';
    });
    const isFormValid = computed(() => {
        return true;
    });

    // 表单验证
    const validateForm = () => {
        return true;
    };

    // 登录函数 - 简化版，直接返回true
    const login = async () => {
        loading.value = true;

        try {
            // 直接返回true，跳过验证
            if (rememberMe.value) {
                localStorage.setItem('rememberedEmail', email.value);
                localStorage.setItem('rememberedPW', password.value);
            } else {
                localStorage.removeItem('rememberedEmail');
                localStorage.removeItem('rememberedPW');
            }

            return true;
        } catch (err) {
            error.value = '登录失败';
            return false;
        } finally {
            loading.value = false;
        }
    };

    // 退出登录
    const logout = () => {
        router.push('/');
    };

    // 检查登录状态并恢复记住的用户信息
    const checkAuth = () => {
        const rememberedEmail = localStorage.getItem('rememberedEmail');

        if (rememberedEmail) {
            email.value = rememberedEmail;
            password.value = localStorage.getItem('rememberedPW') || '';
            rememberMe.value = true;
        }
    };

    // 获取用户ID
    const getUserId = () => {
        return 'local_user';
    };

    // 检查是否已登录
    const isLoggedIn = () => {
        return true;
    };

    return {
        // 状态
        email,
        password,
        rememberMe,
        loading,
        error,

        // 计算属性
        userInitial,
        isFormValid,

        // 方法
        login,
        logout,
        checkAuth,
        getUserId,
        isLoggedIn,
        validateForm
    };
}